pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(address caller, bytes32 assertionId, bool assertedTruthfully) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        bool ok;
        try c.assertionResolvedCallback(assertionId, assertedTruthfully) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "assertionResolvedCallback did not revert for non-optimisticAsserter");
    }
}
